cliBlocks.content:
Get-Content .terraform\modules\modules.json
Test-Path .terraform.lock.hcl
if (Test-Path .terraform.lock.hcl) { Select-String -Path .terraform.lock.hcl -SimpleMatch "cloudposse/label/null" }

